% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"angleFill","hex":"E8DEF4","reason":"identifies the angle between the reflection rays"},{"name":"imageRay","hex":"EF6068","reason":"distinguishes rays to the successive point images from reflection rays"}],"reference":"teacher page 73 question 3(a)"}
\begin{tikzpicture}[x=1cm,y=1cm,line cap=round,line join=round,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{angleFill}{HTML}{E8DEF4}
\definecolor{imageRay}{HTML}{EF6068}
\coordinate (O) at (0,0);
\coordinate (A) at (2.6,2.6);
\coordinate (B) at (3.7,0);
\coordinate (Pzero) at ({3*cos(-15)},{3*sin(-15)});
\coordinate (Pone) at ({3*cos(15)},{3*sin(15)});
\coordinate (Ptwo) at ({3*cos(75)},{3*sin(75)});
\path[fill=angleFill] (O)--(0.8,0) arc[start angle=0,end angle=45,radius=0.8]--cycle;
\draw[black,line width=0.8pt] (A)--(O)--(B);
\draw[imageRay,line width=0.8pt] (O)--(Pzero) (O)--(Pone) (O)--(Ptwo);
\fill[black] (O) circle (1.1pt) (Pzero) circle (1.1pt) (Pone) circle (1.1pt) (Ptwo) circle (1.1pt);
\node[below left] at (O) {$O$};
\node[above right] at (A) {$A$};
\node[right] at (B) {$B$};
\node[right] at (Pzero) {$P_0$};
\node[right] at (Pone) {$P_1$};
\node[right] at (Ptwo) {$P_2$};
\end{tikzpicture}

